SELECT id,source_id,session_id,node_id,node_generation,control_epoch,kind,request_hash,state,reason,sent_bytes,received_bytes,elapsed_ms,sequence,report_hash,revision,created_at,updated_at,ended_at FROM pixels.connection_observations WHERE ($1::uuid IS NULL OR id>$1) AND ($2::uuid IS NULL OR session_id=$2) ORDER BY id LIMIT $3
